async function exec(tool,args){return new Promise((resolve,reject)=>{const child=spawn(tool,args,{stdio:['ignore','pipe','pipe']});active.add(child.pid);const stdout=[],stderr=[];child.stdout.on('data',c=>stdout.push(c));child.stderr.on('data',c=>stderr.push(c));child.once('error',reject);child.once('close',code=>{active.delete(child.pid);if(code)reject(Error(path.basename(tool)+' exited '+code+': '+Buffer.concat(stderr).toString().slice(-2500)));else resolve(Buffer.concat(stdout));});});}
